inline std::string_view manualMarketNoticeMessageKeyName(ManualMarketNoticeMessageKey key){
    static constexpr std::array<std::string_view,manualMarketNoticeMessageKeyCount> names={{"manual_market.notice.invalid_decimal","manual_market.notice.invalid_validity","manual_market.notice.invalid_skew","manual_market.notice.invalid_reference","manual_market.notice.saved_cli_disabled","manual_market.notice.saved","manual_market.notice.save_failed","manual_market.notice.clock_unavailable","manual_market.notice.stamped_now"}};
    const auto index=static_cast<std::size_t>(key);return index<names.size()?names[index]:std::string_view{};
}
inline LocalizedMessage manualMarketNoticeMessage(std::string_view language,ManualMarketNoticeMessageKey key){
    const auto index=static_cast<std::size_t>(key);if(index>=manualMarketNoticeMessageKeyCount)return {};
    const auto &source=manualMarketNoticeLocalePacks()[0];const auto *selected=&source;for(const auto &pack:manualMarketNoticeLocalePacks())if(pack.id==language){selected=&pack;break;}
    if(selected->id!=language||!validTemplateTranslation(source.messages[index],selected->messages[index]))return {source.messages[index],source.id,source.review,true,false};
    return {selected->messages[index],selected->id,selected->review,false,selected->rtl};
}
inline std::string manualMarketNoticeEnglish(ManualMarketNoticeMessageKey key){return std::string(manualMarketNoticeMessage("en",key).text);}
